INSERT INTO op (seq, action_key, status, temp_id, base_revision, created_at, dedupe_key, since) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?6) ON CONFLICT (seq) DO UPDATE SET action_key = excluded.action_key, status = excluded.status, temp_id = excluded.temp_id, base_revision = excluded.base_revision, created_at = excluded.created_at, dedupe_key = excluded.dedupe_key